"use client";

import { useState } from "react";

type Course = { subject_id?: string; subject_name?: string; credit?: number; grade_earn?: string };
type Semester = { year?: number; sem_num?: number; GPA?: string; subject?: Course[] };
type RecordData = {
  format_id?: string;
  header_detail?: { student_id?: string; prename?: string; name?: string; program?: string };
  transcript_detail?: { semesters?: Semester[]; total_credits_earned?: number; cumulative_gpa?: string };
};
type ValidationIssue = { path: string; code: string; message: string; severity: "error" | "warning" };
type Validation = { needs_review: boolean; errors: number; warnings: number; course_count: number; issues: ValidationIssue[] };
type Extraction = { filename: string; engine: string; processing_seconds: number; record: RecordData; validation?: Validation; error?: string };
type Grade = { student_id: string; academic_year: string; semester_number: string; subject_id: string; subject_name: string; grade: string };

async function api(path: string, init?: RequestInit) {
  const response = await fetch("/api/proxy/" + path, { cache: "no-store", ...init });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.detail || "HTTP " + response.status);
  return data;
}

export default function Home() {
  const [currentTab, setCurrentTab] = useState<"upload" | "search">("upload");
  const [files, setFiles] = useState<File[]>([]);
  const [isDragging, setIsDragging] = useState(false);
  const [results, setResults] = useState<Extraction[]>([]);
  const [selected, setSelected] = useState(0);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const [progress, setProgress] = useState("");
  
  const [studentId, setStudentId] = useState("");
  const [grades, setGrades] = useState<Grade[]>([]);

  const [showJsonEditor, setShowJsonEditor] = useState(false);
  const [editor, setEditor] = useState("");

  const current = results[selected];
  let record: RecordData | undefined;
  let jsonError = "";
  if (current && !current.error) {
    try { record = JSON.parse(editor) as RecordData; }
    catch { jsonError = "JSON ไม่ถูกต้อง กรุณาตรวจวงเล็บและเครื่องหมาย"; }
  }
  const semesters = record?.transcript_detail?.semesters || [];
  const courses = semesters.reduce((count, semester) => count + (semester.subject?.length || 0), 0);

  function select(index: number) {
    setSelected(index);
    setEditor(JSON.stringify(results[index].record, null, 2));
    setMessage("");
  }

  async function extractAll(filesToExtract: File[]) {
    if (!filesToExtract.length) return;
    setBusy(true); setMessage(""); setResults([]); setSelected(0);
    const next: Extraction[] = [];
    try {
      for (let i = 0; i < filesToExtract.length; i++) {
        setProgress("กำลังอ่าน " + (i + 1) + "/" + filesToExtract.length + ": " + filesToExtract[i].name);
        const form = new FormData();
        form.append("file", filesToExtract[i]);
        form.append("format_id", "auto");
        try {
          const value = await api("transcripts/extract", { method: "POST", body: form }) as Extraction;
          next.push(value);
          if (next.length === 1) setEditor(JSON.stringify(value.record, null, 2));
        } catch (error) {
          next.push({ filename: filesToExtract[i].name, engine: "", processing_seconds: 0, record: {}, error: String(error) });
        }
        setResults([...next]);
      }
      const passed = next.filter(item => !item.error);
      const seconds = passed.reduce((sum, item) => sum + item.processing_seconds, 0);
      setMessage("อ่านสำเร็จ " + passed.length + " ฉบับ");
    } finally { setBusy(false); setProgress(""); }
  }

  async function save() {
    if (!current || !record || jsonError) return;
    setBusy(true); setMessage("");
    try {
      const result = await api("documents", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ filename: current.filename, record, engine: current.engine, processing_seconds: current.processing_seconds }),
      });
      setMessage("บันทึกสำเร็จ รหัส: " + result.document_id);
    } catch (error) { setMessage("บันทึกไม่สำเร็จ: " + String(error)); }
    finally { setBusy(false); }
  }

  async function search() {
    if (!studentId.trim()) { setMessage("กรุณากรอกรหัสนักศึกษา"); return; }
    setBusy(true); setMessage("");
    try {
      const params = new URLSearchParams({ student_id: studentId.trim() });
      const result = await api("grades?" + params.toString());
      setGrades(result.results || []);
      if (result.results?.length === 0) setMessage("ไม่พบข้อมูล");
    } catch (error) { setMessage("ค้นหาไม่สำเร็จ: " + String(error)); }
    finally { setBusy(false); }
  }

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const selectedFiles = Array.from(e.target.files);
      setFiles(selectedFiles);
      extractAll(selectedFiles);
    }
  };

  return (
    <div className="min-h-screen bg-[#F8F7F5] text-[#292825] font-['IBM_Plex_Sans_Thai']">
      {/* Header */}
      <header className="h-[72px] bg-white flex items-center px-12 border-b border-[#E7E4DE]">
        <div className="flex items-center gap-4">
          <div className="w-12 h-7 bg-[#ED0A13] rounded-[2px] flex items-center justify-center">
            <span className="font-['Inter'] font-black text-[12px] text-white tracking-widest">LOSO</span>
          </div>
          <h1 className="font-semibold text-[18px] text-[#292825]">Transcript OCR Studio</h1>
        </div>
      </header>

      <div className="flex px-6 py-6 gap-6 max-w-[1440px] mx-auto h-[calc(100vh-72px)] overflow-hidden">
        {/* Sidebar */}
        <aside className="w-[224px] flex-shrink-0 bg-white rounded-[20px] border border-[#E7E4DE] p-4 flex flex-col h-full overflow-y-auto">
          <div className="text-[11px] text-[#716F6A] mb-2 px-2 tracking-wider font-semibold">WORKSPACE</div>
          
          <nav className="flex flex-col gap-1 mb-6">
            <button 
              onClick={() => { setCurrentTab("upload"); setResults([]); setGrades([]); setMessage(""); }}
              className={`flex items-center gap-3 px-3 py-3 rounded-xl text-left transition-colors ${currentTab === "upload" ? "bg-[#F47721] text-white" : "text-[#262626] hover:bg-slate-50"}`}
            >
              <span className="font-semibold text-lg leading-none">↑</span>
              <span className="font-semibold text-[14px]">นำเข้า Transcript</span>
            </button>
            <button 
              onClick={() => { setCurrentTab("search"); setResults([]); setMessage(""); }}
              className={`flex items-center gap-3 px-3 py-3 rounded-xl text-left transition-colors ${currentTab === "search" ? "bg-[#F47721] text-white" : "text-[#262626] hover:bg-slate-50"}`}
            >
              <span className="font-semibold text-lg leading-none">⌕</span>
              <span className="font-semibold text-[14px]">ค้นหาผลการเรียน</span>
            </button>
          </nav>

          <div className="h-[1px] bg-[#E7E4DE] mx-2 mb-6"></div>

          <div className="text-[11px] text-[#716F6A] mb-3 px-2 tracking-wider font-semibold">เอกสารล่าสุด</div>
          {results.length > 0 && results.map((res, i) => (
             <div key={i} onClick={() => { setCurrentTab("upload"); select(i); }} className="px-2 mb-4 cursor-pointer group">
               <div className={`text-[13px] truncate ${selected === i && currentTab === "upload" ? "text-[#F47721] font-semibold" : "text-[#292825] group-hover:text-[#F47721]"}`}>{res.filename}</div>
               <div className="text-[11px] text-[#716F6A] mt-1">{res.error ? "อ่านไม่สำเร็จ" : "อ่านสำเร็จ"}</div>
             </div>
          ))}
          {results.length === 0 && (
             <div className="px-2 text-[12px] text-[#716F6A]">ยังไม่มีเอกสาร</div>
          )}

          <div className="mt-auto pt-6">
            <div className="bg-white border border-[#E7E4DE] rounded-2xl p-4">
              <div className="text-[12px] text-[#292825] font-semibold">ต้องการความช่วยเหลือ?</div>
              <div className="text-[11px] text-[#716F6A] mt-2 leading-relaxed">คู่มือถ่ายเอกสารให้ OCR อ่านแม่นยำ</div>
              <button className="text-[11px] text-[#F47721] mt-3 flex items-center gap-1 font-semibold hover:underline">
                เปิดคู่มือ <span className="text-[14px]">→</span>
              </button>
            </div>
          </div>
        </aside>

        {/* Main Content */}
        <main className="flex-1 overflow-y-auto pr-2 pb-10">
          
          {message && (
            <div className="mb-6 rounded-xl border border-blue-200 bg-blue-50 px-4 py-3 text-sm text-blue-900">
              {message}
            </div>
          )}

          {currentTab === "upload" && results.length === 0 && !busy && (
            <div className="max-w-[1040px]">
              <div className="text-[28px] font-semibold text-[#292825] mb-2">นำเข้า Transcript</div>
              <div className="text-[14px] text-[#716F6A] mb-8 font-semibold">เลือกไฟล์จากอุปกรณ์ หรือนำข้อมูลจากภาพถ่ายเข้าสู่ระบบ</div>

              <div className="flex gap-6 items-start flex-col xl:flex-row">
                {/* Upload Zone */}
                <label 
                  onDragOver={e => { e.preventDefault(); setIsDragging(true); }}
                  onDragLeave={e => { e.preventDefault(); setIsDragging(false); }}
                  onDrop={e => {
                    e.preventDefault();
                    setIsDragging(false);
                    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
                      const selectedFiles = Array.from(e.dataTransfer.files);
                      setFiles(selectedFiles);
                      extractAll(selectedFiles);
                    }
                  }}
                  className={`flex-1 w-full min-h-[360px] bg-white border border-[#E7E4DE] rounded-[24px] flex flex-col items-center justify-center cursor-pointer hover:bg-slate-50 transition-colors ${isDragging ? 'border-[#F47721] bg-orange-50' : ''}`}
                >
                  <input type="file" multiple accept=".pdf,.png,.jpg,.jpeg" className="hidden" onChange={handleFileChange} />
                  <div className="w-[72px] h-[72px] bg-white border border-[#E7E4DE] rounded-[20px] shadow-sm flex items-center justify-center mb-6">
                    <span className="text-[26px] font-semibold text-[#292825]">↑</span>
                  </div>
                  <div className="text-[18px] font-semibold text-[#292825] mb-2">วางไฟล์ Transcript ที่นี่</div>
                  <div className="text-[13px] text-[#716F6A] mb-6">รองรับ PDF, JPG และ PNG · สูงสุด 10 MB</div>
                  
                  <div className="flex gap-3 w-full max-w-[404px] justify-center">
                    <div className="w-[196px] bg-[#F47721] text-white h-[44px] rounded-[14px] flex items-center justify-center text-[13px] font-medium transition-colors hover:bg-orange-600">
                      เลือกไฟล์จากอุปกรณ์
                    </div>
                    {/* Simulated camera button */}
                    <div className="w-[196px] bg-white border border-[#E7E4DE] text-[#292825] h-[44px] rounded-[14px] flex items-center justify-center text-[13px] hover:bg-slate-50 transition-colors">
                      เปิดกล้องเพื่อถ่ายรูป
                    </div>
                  </div>
                </label>

                {/* Quality Guidance Card */}
                <div className="w-[304px] flex-shrink-0 bg-white border border-[#E7E4DE] rounded-[18px] p-6 shadow-sm">
                  <div className="font-semibold text-[14px] text-[#292825] mb-1">เพื่อให้ OCR อ่านได้แม่นยำ</div>
                  <div className="text-[11px] text-[#716F6A] mb-4">แนะนำก่อนเลือกไฟล์</div>
                  
                  <ul className="text-[12px] text-[#292825] space-y-3 mb-6">
                    <li>- ใช้ PDF ต้นฉบับเป็นตัวเลือกแรก</li>
                    <li>- ภาพต้องคม ชัด และอ่านตัวอักษรได้</li>
                    <li>- ไม่เอียง ไม่กลับหัว และไม่ครอปข้อมูล</li>
                    <li>- หลีกเลี่ยงเงาและแสงสะท้อน</li>
                  </ul>
                  
                  <button className="text-[11px] font-semibold text-[#F47721] flex items-center gap-1 hover:underline">
                    ดู checklist ฉบับเต็ม <span className="text-[14px]">→</span>
                  </button>
                </div>
              </div>
            </div>
          )}

          {busy && (
            <div className="flex flex-col items-center justify-center h-full pt-20">
              <div className="w-[72px] h-[72px] border-4 border-[#F47721] border-t-transparent rounded-full animate-spin mb-6"></div>
              <div className="text-[18px] font-semibold text-[#292825] mb-2">กำลังประมวลผล</div>
              <div className="text-[14px] text-[#716F6A]">{progress || "โปรดรอสักครู่..."}</div>
            </div>
          )}

          {currentTab === "upload" && current && !busy && (
            <div className="flex gap-6 max-w-[1440px] items-start flex-col xl:flex-row">
              {/* Review Section */}
              <div className="flex-1 w-full min-w-0">
                <div className="text-[11px] text-[#716F6A] uppercase tracking-wider mb-2">TRANSCRIPT / {record?.header_detail?.student_id || "UNKNOWN"}</div>
                <div className="flex justify-between items-end mb-4">
                  <div>
                    <div className="text-[30px] font-semibold text-[#292825] leading-tight mb-2">ตรวจข้อมูลก่อนบันทึก</div>
                    <div className="text-[14px] text-[#716F6A] font-semibold">ผลลัพธ์จาก OCR พร้อมให้ตรวจสอบและแก้ไขก่อนบันทึกเข้าสู่ระบบ</div>
                  </div>
                  <button onClick={save} disabled={busy || !!jsonError} className="bg-[#292825] text-white h-[46px] px-8 rounded-[14px] text-[14px] font-medium hover:bg-black transition-colors disabled:opacity-50 flex-shrink-0">
                    บันทึกผลที่ตรวจแล้ว
                  </button>
                </div>

                {/* Student Info Card */}
                <div className="bg-white border border-[#E7E4DE] rounded-[22px] p-6 mb-6 shadow-sm relative">
                  <div className="flex justify-between items-start mb-6">
                    <div className="text-[15px] font-semibold text-[#292825]">ข้อมูลนักศึกษา</div>
                    
                    {current.validation && (
                       <div className="bg-white border border-[#E7E4DE] h-[30px] px-3 rounded-[15px] flex items-center gap-2">
                         <div className={`w-1.5 h-1.5 rounded-full ${current.validation.needs_review ? "bg-[#F47721]" : "bg-[#3E8D67]"}`}></div>
                         <div className="text-[11px] text-[#292825]">OCR confidence {current.validation.needs_review ? "ต่ำ" : "สูง"}</div>
                       </div>
                    )}
                  </div>

                  <div className="flex flex-wrap items-center">
                    <div className="pr-12 border-r border-[#E7E4DE] mb-4 lg:mb-0">
                      <div className="text-[11px] text-[#716F6A] mb-1">รหัสนักศึกษา</div>
                      <div className="text-[23px] font-semibold text-[#292825]">{record?.header_detail?.student_id || "—"}</div>
                    </div>
                    <div className="px-12 border-r border-[#E7E4DE] mb-4 lg:mb-0">
                      <div className="text-[11px] text-[#716F6A] mb-1">ชื่อ - นามสกุล</div>
                      <div className="text-[17px] font-semibold text-[#292825] pt-1">{(record?.header_detail?.prename || "") + " " + (record?.header_detail?.name || "—")}</div>
                    </div>
                    <div className="px-12 border-r border-[#E7E4DE] mb-4 lg:mb-0">
                      <div className="text-[11px] text-[#716F6A] mb-1">คณะ</div>
                      <div className="text-[23px] font-semibold text-[#292825]">{record?.header_detail?.program || "—"}</div>
                    </div>
                    <div className="pl-12">
                      <div className="text-[11px] text-[#716F6A] mb-1">เกรดเฉลี่ยสะสม</div>
                      <div className="text-[23px] font-semibold text-[#292825]">{record?.transcript_detail?.cumulative_gpa || "—"}</div>
                    </div>
                  </div>

                  <div className="mt-8 pt-4 border-t border-[#E7E4DE] text-[12px] text-[#3E8D67]">
                    อ่านเอกสารสำเร็จแล้ว · ข้อมูล {courses} รายวิชาพร้อมตรวจสอบ
                  </div>
                </div>

                {/* Course Table */}
                <div className="bg-white border border-[#E7E4DE] rounded-[22px] shadow-sm overflow-hidden">
                  <div className="p-6 flex justify-between items-center border-b border-[#E7E4DE]">
                    <div className="text-[16px] font-semibold text-[#292825]">รายวิชาที่อ่านจากเอกสาร</div>
                    <div className="text-[12px] text-[#716F6A]">{courses} รายวิชา</div>
                  </div>
                  
                  <div className="overflow-x-auto">
                    <table className="w-full text-left">
                      <thead className="text-[11px] text-[#716F6A]">
                        <tr>
                          <th className="px-6 py-4 font-normal">รหัสวิชา</th>
                          <th className="px-6 py-4 font-normal">ชื่อรายวิชา</th>
                          <th className="px-6 py-4 font-normal">หน่วยกิต</th>
                          <th className="px-6 py-4 font-normal">เกรด</th>
                          <th className="px-6 py-4 font-normal">สถานะ</th>
                        </tr>
                      </thead>
                      <tbody className="text-[13px] text-[#292825]">
                        {semesters.flatMap(sem => sem.subject || []).map((course, idx) => (
                          <tr key={idx} className="border-t border-[#E7E4DE]">
                            <td className="px-6 py-4 font-mono text-[#292825]">{course.subject_id}</td>
                            <td className="px-6 py-4 text-[#292825]">{course.subject_name}</td>
                            <td className="px-6 py-4 text-[#292825]">{course.credit}</td>
                            <td className="px-6 py-4 font-semibold text-[#292825]">{course.grade_earn?.toUpperCase()}</td>
                            <td className="px-6 py-3">
                              <div className="inline-flex items-center h-[26px] px-3 bg-white border border-[#E7E4DE] rounded-[13px] text-[10px]">
                                {course.subject_name?.includes("?") || course.subject_id?.includes("?") || current.validation?.needs_review ? (
                                  <span className="text-[#A96519]">ตรวจสอบ</span>
                                ) : (
                                  <span className="text-[#3E8D67]">ตรวจแล้ว</span>
                                )}
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>

              {/* Right Sidebar for JSON Editing and Alerts */}
              <div className="w-full xl:w-[301px] flex-shrink-0 flex flex-col gap-6">
                
                {current.validation?.needs_review && (
                  <div className="bg-white border border-[#E7E4DE] rounded-[22px] p-6 shadow-sm">
                    <div className="flex items-center gap-3 mb-3">
                      <div className="w-7 h-7 bg-white border border-[#E7E4DE] rounded-[14px] flex items-center justify-center text-[#A96519] font-bold">!</div>
                      <div className="text-[14px] font-semibold text-[#292825]">พบข้อมูลที่ควรตรวจสอบ</div>
                    </div>
                    <div className="text-[12px] text-[#716F6A] mb-5">{current.validation.issues[0]?.message || "โปรดตรวจสอบข้อมูล"}</div>
                    <button className="text-[12px] text-[#F47721] hover:underline" onClick={() => setShowJsonEditor(true)}>
                      ตรวจสอบรายการ
                    </button>
                  </div>
                )}

                <div className="bg-white border border-[#E7E4DE] rounded-[22px] p-6 shadow-sm">
                  <div className="flex justify-between items-center mb-4">
                    <div className="text-[14px] font-semibold text-[#292825]">คุณภาพการอ่านเอกสาร</div>
                    <div className="text-[14px] text-[#F47721]">98%</div>
                  </div>
                  <div className="h-2 bg-[#E7E4DE] rounded-full overflow-hidden mb-4">
                    <div className="h-full bg-[#F47721] w-[98%] rounded-full"></div>
                  </div>
                  <div className="text-[12px] text-[#716F6A]">
                    ตัวอักษรชัดเจน · PDF
                  </div>
                </div>

                <div className="bg-white border border-[#E7E4DE] rounded-[18px] p-6 shadow-sm">
                  <div className="flex justify-between items-center mb-3">
                    <div className="text-[16px] font-semibold text-[#292825]">{"{ }"} JSON editor</div>
                    <button onClick={() => setShowJsonEditor(!showJsonEditor)} className="text-[18px] font-bold text-[#F47721]">→</button>
                  </div>
                  <div className="text-[12px] text-[#716F6A] mb-5 leading-relaxed">ตรวจ แก้ไข และจัดรูปแบบข้อมูลดิบ<br/>ในพื้นที่สำหรับแก้ไขโดยเฉพาะ</div>
                  <button onClick={() => setShowJsonEditor(!showJsonEditor)} className="text-[12px] font-semibold text-[#F47721] hover:underline">
                    {showJsonEditor ? "ปิด JSON editor" : "เปิด JSON editor เต็มหน้า →"}
                  </button>
                  
                  {showJsonEditor && (
                    <div className="mt-4">
                      <textarea
                        spellCheck={false}
                        value={editor}
                        onChange={e => setEditor(e.target.value)}
                        className="w-full h-80 bg-slate-900 text-slate-100 rounded-xl p-4 font-mono text-xs border border-slate-700 focus:outline-none focus:border-[#F47721]"
                      />
                      {jsonError && <div className="text-red-500 text-xs mt-2">{jsonError}</div>}
                    </div>
                  )}
                </div>

              </div>
            </div>
          )}

          {currentTab === "search" && (
            <div className="max-w-[800px]">
              <div className="text-[28px] font-semibold text-[#292825] mb-2">ค้นหาผลการเรียน</div>
              <div className="text-[14px] text-[#716F6A] mb-8 font-semibold">ค้นหาประวัติและผลการเรียนในฐานข้อมูล</div>

              <div className="bg-white border border-[#E7E4DE] rounded-[24px] p-8 shadow-sm mb-8">
                <div className="max-w-md flex flex-col gap-4">
                  <div>
                    <label className="block text-[12px] text-[#716F6A] mb-2">รหัสนักศึกษา</label>
                    <input 
                      type="text" 
                      value={studentId} 
                      onChange={e => setStudentId(e.target.value)}
                      placeholder="เช่น 67070127"
                      className="w-full h-[44px] px-4 bg-white border border-[#E7E4DE] rounded-[14px] text-[14px] focus:outline-none focus:border-[#F47721]"
                    />
                  </div>
                  <button 
                    onClick={search}
                    disabled={busy}
                    className="h-[44px] bg-[#F47721] text-white rounded-[14px] text-[14px] font-medium hover:bg-orange-600 transition-colors disabled:opacity-50 mt-2"
                  >
                    ค้นหาในฐานข้อมูล
                  </button>
                </div>
              </div>

              {grades.length > 0 && (
                <div className="bg-white border border-[#E7E4DE] rounded-[22px] shadow-sm overflow-hidden">
                  <div className="p-6 border-b border-[#E7E4DE]">
                    <div className="text-[16px] font-semibold text-[#292825]">ผลการค้นหา ({grades.length} รายการ)</div>
                  </div>
                  <table className="w-full text-left text-[13px] text-[#292825]">
                    <thead className="bg-[#F8F7F5] text-[11px] text-[#716F6A] border-b border-[#E7E4DE]">
                      <tr>
                        <th className="px-6 py-4 font-normal">รหัสวิชา</th>
                        <th className="px-6 py-4 font-normal">ชื่อรายวิชา</th>
                        <th className="px-6 py-4 font-normal">ภาคการศึกษา</th>
                        <th className="px-6 py-4 font-normal">เกรด</th>
                      </tr>
                    </thead>
                    <tbody>
                      {grades.map((grade, idx) => (
                        <tr key={idx} className="border-b border-[#E7E4DE] last:border-0">
                          <td className="px-6 py-4 font-mono">{grade.subject_id}</td>
                          <td className="px-6 py-4">{grade.subject_name}</td>
                          <td className="px-6 py-4">{grade.semester_number}/{grade.academic_year}</td>
                          <td className="px-6 py-4 font-semibold text-[14px]">{grade.grade?.toUpperCase()}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          )}

        </main>
      </div>
    </div>
  );
}
